text:
/* ---------- 顶栏 ---------- */
.nook-reader-head {
  background: #4c917c !important;
  border-bottom: none !important;
  box-shadow: none !important;
}

.nook-reader-head .nook-icon-btn {
  color: #ffffff !important;
}

.nook-reader-head .nook-icon-btn:hover {
  color: #57796e !important;
  background-color: transparent !important;
}

.nook-reader-title {
  color: #ffffff !important;
  text-shadow: none;
}

/* ---------- 工具栏 ---------- */
.nook-reader-toolbar {
  background: #4c917c;
  border-bottom: none !important;
  gap: 10px !important;
}

.nook-chip {
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  font-size: clamp(8px, 2.5vw, 12px);
  font-weight: bold !important;
  color: #4c917c !important;
  background: #e8f0ec !important;
  border: 1px solid #4c917c !important;
}

.nook-chip:hover {
  background: #8fb6a5 !important;
  border-color: #57796e !important;
  color: #57796e !important;
}

.nook-chip svg {
  color: #4c917c !important;
  stroke: #4c917c !important;
}

.nook-chip:hover svg {
	color: #57796e !important;
	stroke: #57796e !important;
}

/* ---------- 正文 ---------- */
.nook-flip-wrap::before ,
.nook-flip-wrap::after {
	display: none !important;
}

.nook-reader-page {
  color: #2b2b2b !important;
}

.nook-para-text {
  color: #2b2b2b !important;
}

.nook-para-text mark {
  background: rgba(76, 145, 124, 0.2) !important;
}

.nook-ch-end {
	display: none !important;
}

.nook-page-nav {
	margin-top: none !important;
	border-top: 1px dashed #57796e !important;
	color: #2b2b2b !important;
}

.nook-page-nav button {
	border: 1px solid #57796e !important;
	background: #57796e !important;
	color: #ffffff !important;
	font-weight: bold !important;
}

.nook-flip-ind {
	color: #2b2b2b !important;
	font-weight: bold !important;
	background: #e8f0ec !important;
	border: 1px solid #57796e !important;
}

.nook-jump {
	background: rgba(255, 255, 255, 0.5) !important;
	border: 1.5px solid #57796e !important;
}

.nook-jump-title {
	color: #57796e !important;
	font-weight: bold !important;
}

.nook-jump-num {
	color: #2b2b2b !important;
}

.nook-jump-go {
	background: #57796e !important;
	font-weight: bold !important;
}

.nook-jump-x {
	color: #000000 !important;
}

.nook-buddy {
	background: #4c917c !important;
	border-top: none !important;
}

.nook-buddy-avatar {
	border-color: #57796e !important;
	background: #e8f0ec !important;
	color: #57796e !important;
}

.nook-buddy-name {
	color: #ffffff !important;
}

.nook-buddy-status {
	color: #f3f3f3 !important;
}

.nook-buddy-ask {
	border: 1px solid #ffffff !important;
 background: #4c917c !important;
}

.nook-ch-orn {
	display: none !important;
}

.nook-ch-title {
	color: #2b2b2b !important;
}

.nook-ch-rule {
	display: none !important;
}

.nook-selbar {
	background: #ffffff !important;
	border-top: none !important;	
}

.nook-selbar-hint {
	color: #2b2b2b !important;
	font-weight: bold !important;
}

.nook-selbar-x {
	color: #000000 !important;
}

.nook-selbar-quote {
	color: #2b2b2b !important;
	background: rgba(76, 145, 124, 0.1);
	border-left: 3px solid rgba(76, 145, 124, 0.6);
}

.nook-mark-sw {
	background: #ffffff !important;
	color: #505050 !important;
	border: 1px solid #57796e !important;
}

.nook-mark-sw.active {
	border-color: #4c917c !important;
	color: #505050 !important;
	background: #e8f0ec !important;
}

.nook-selbar-colorlabel {
	color: #505050 !important;
}

.nook-selbar-step {
	border-color: #4c917c !important;
	background: #4c917c !important;
	color: #ffffff !important;
}

.nook-selbar-actions .nook-selbar-step {
	border-color: #57796e !important;
	background: #e8f0ec !important;
	color: #505050 !important;
}

.nook-selbar-step svg {
	color: #000000 !important;
	stroke: #000000 !important;
}

.nook-selbar-ask {
	color: #ffffff !important;
	border: none !important;
	background: #4c917c !important;
}

.nook-buddy-panel {
	background: #ffffff !important;
	border: 1px solid #57796e !important;
}

.nook-buddy-panel-head {
	background: #4c917c !important;
	border-bottom: none !important;
	color: #ffffff !important;
}

.nook-buddy-panel-head svg {
	color: #ffffff !important;
	stroke: #ffffff !important;
}

.nook-buddy-empty {
	font-weight: bold !important;
}

.nook-buddy-input {
	border-top: 1px solid #4c917c !important;
}

.nook-buddy-input input {
	color: #2b2b2b !important;
}

.nook-buddy-input input::placeholder {
  color: #888888 !important;
}

.lucide.lucide-send {
	color: #2b2b2b !important;
	stroke: #2b2b2b !important;
}

.nook-toc {
	background: #ffffff !important;
}

.nook-toc-head {
	background: #4c917c !important;
	border-bottom: none !important;
}

.nook-toc-head span {
  color: #ffffff !important;
}

.nook-toc-head .nook-icon-btn {
	color: #ffffff !important;
}

.nook-toc-num {
	color: #4c917c !important;
}

.nook-toc-name {
	color: #2b2b2b !important;
}

.nook-toc-item.active {
	background: rgba(76, 145, 124, 0.1) !important;
}

.nook-letter {
	background: linear-gradient(180deg, #ffffff, #e8f0ec) !important;
	border: none !important;
	color: #ffffff !important;
}

.nook-letter-head {
	background: #4c917c !important;
	border-bottom: none !important;
}

.nook-letter-head svg {
	color: #ffffff !important;
	stroke: #ffffff !important;
}

.nook-letter-empty svg {
	color: #57796e !important;
	stroke: #57796e !important;
}

.book-nook-screen p {
	font-size: 12px !important;
}

.nook-letter-btn {
	background: #4c917c !important;
}

.nook-letter-btn .lucide.lucide-sparkles {
	color: #ffffff !important;
	stroke: #ffffff !important;
}

.nook-letter-sign {
	color: #57796e !important;
}

.nook-letter-date {
	color: #3a5149 !important;
}

.nook-letter-btn.ghost {
	color: #ffffff !important;
	border: none !important;
}

.nook-modal-close .lucide.lucide-x {
	color: #ffffff !important;
	stroke: #ffffff !important;
}

.lucide.lucide-refresh-cw {
	color: #ffffff !important;
	stroke: #ffffff !important;
}

.nook-set-sheet.nook-audio-sheet {
	background: #ffffff !important;
	color: #505050 !important;
}

.nook-set-head span {
	color: #000000 !important;
}

.nook-icon-btn.active {
	background: transparent !important;
}

.lucide.lucide-x {
	color: #000000 !important;
	stroke: #000000 !important;
}

.nook-set-label {
	color: #505050 !important;
}

.nook-set-sheet .nook-audio-sheet {
	background: #ffffff !important;
	color: #888888 !important;
}

.nook-aloud-step {
	border: 1px solid #8fb6a5 !important;
	background: #e8f0ec !important;
	color: #888888 !important;
}

.nook-aloud-play {
	border: none !important;
	background: #4c917c !important;
	color: #ffffff !important;
}

.lucide.lucide-skip-back,
.lucide.lucide-skip-forward {
	color: #888888 !important;
	stroke: #888888 !important;
}

.nook-aloud-start {
	background: #4c917c !important;
	color: #ffffff !important;
}

.nook-set-seg button {
	border: 1px solid #8fb6a5 !important;
	background: #e8f0ec !important;
	color: #888888 !important;
}

.nook-set-seg button.active {
	border: none !important;
	background: #4c917c !important;
	color: #ffffff !important;
}

.nook-audio-sublabel {
	color: #505050 !important;
}

.nook-audio-chip {
	border: 1px solid #8fb6a5 !important;
	color: #505050 !important;
}

.nook-audio-chip.active {
	border: 1px solid #4c917c !important;
	color: #2b2b2b !important;
	background: #8fb6a5 !important;
}

.lucide.lucide-volume2.lucide-volume-2 {
	color: #505050 !important;
	stroke: #505050 !important;
}

.nook-audio-addform input {
	border: 1px solid #8fb6a5 !important;
	background: #e8f0ec !important;
	color: #505050 !important;
}

.nook-audio-addform input:focus {
	border-color: #4c917c !important;
}

.nook-sleep-remain {
	color: #2b2b2b !important;
}

.nook-set-sheet {
	color: #2b2b2b !important;
	background: #ffffff !important;
}

.nook-set-css {
	border: 1px solid #57796e !important;
	color: #505050 !important;
	background: #e8f0ec !important;
}

.nook-set-fonts button {
	border: 1px solid #57796e !important;
	background: #e8f0ec !important;
	color: #2b2b2b !important;
}

.nook-set-fonts button.active {
	border: 1px solid #3a5149 !important;
	background: #8fb6a5 !important;
	color: #2b2b2b !important;
}

.nook-set-bg-btn {
	border: 1px solid #4c917c !important;
	background: #4c917c !important;
	color: #ffffff !important;
	font-weight: bold !important;
}

.nook-set-bg-clear {
	border: 1px solid #57796e !important;
	background: #e8f0ec !important;
	color: #2b2b2b !important;
}

.nook-set-row{
	border-top: 1px solid #3a5149 !important;
}

.nook-set-stepper button{
	border: 1px solid #57796e !important;
	background: #e8f0ec !important;
	color: #2b2b2b !important;
}

.nook-buddy-bubble {
	border: 1px solid #57796e !important;
	color: #505050 !important;
	background: #ffffff !important;
}

.nook-buddy-typing {
	color: #505050 !important;
}

.lucide.lucide-loader.nook-spin{
	color: #505050 !important;
	stroke: #505050 !important;
}

.nook-selbar-noteinput input {
	border: 1px solid #57796e !important;
	background: #ffffff !important;
	color: #505050 !important;
}

.nook-selbar-noteinput input::placeholder{
	color: #888888 !important;
}

.nook-selbar-noteinput input:focus{
	border-color: #57796e !important;
}

.nook-compose-quote {
	border-top: #4c917c !important;
	background: rgba(76, 145, 124, 0.1) !important;
}

.nook-reader .nook-compose-q {
	color: #505050 !important;
	border-left: rgba(76, 145, 124, 0.7) !important;
}

.nook-para-mark {
	background: #e8f0ec !important;
	border: 1px solid #57796e !important;
}

.nook-para-mark.nook-usernote-mark {
	background: #f3f3f3 !important;
	border: 1px solid #888888 !important;
}

.nook-note {
	background: #ffffff !important;
	border: 1px solid rgba(76, 145, 124, 0.85);
	border-left: 4px solid rgba(76, 145, 124, 0.85) !important;
}

.nook-note-ava {
	background: #e8f0ec !important;
	color: #4c917c !important;
}

.nook-note-ava svg {
	color: #4c917c !important;
	stroke: #4c917c !important;
}

.nook-note-name {
	color: #2b2b2b !important;
}

.nook-note-x svg {
	color: #2b2b2b !important;
	stroke: #2b2b2b !important;
}

.nook-note-quote {
	color: #2b2b2b !important;
	border-left: rgba(76, 145, 124, 0.7) !important;
	background: rgba(76, 145, 124, 0.1);
}

.nook-note-body p {
	color: #2b2b2b !important;
}

.nook-note-pending {
	color: #505050 !important;
	background: transparent !important;
}

.nook-note-ask {
	background: #4c917c !important;
}

.nook-warn-chip {
    background: #8a2121;
}

